{"filePath":"/Users/dev02/Desktop/1400Project/gat1400dbserver/mysql_total_user_combo_info.go","content":"package main

import (
	"fmt"
	"gopkgs/pkg/utils"
	"time"
)

/*
 * @FuncName: db1400 - 开始用户套餐包统计信息工作线程池
 * @Version: v1.0.0
 * @Description: db1400 - 开始用户套餐包统计信息工作线程池
 * @Param: 无
 */
func (provider *MysqlProvider) StartTotalUserComboInfoWorkThread(server *VIIDFeatureServer) error {

	// 开始工作线程
	provider.totalUserComboThreadIsRunning = true
	go provider.TotalUserComboInfoWorkThreadProc(server)

	return nil
}

/*
 * @FuncName: db1400 - 用户套餐包统计信息线程处理函数
 * @Version: v1.0.0
 * @Description: db1400 - 用户套餐包统计信息线程处理函数
 * @Param: 无
 */
func (provider *MysqlProvider) TotalUserComboInfoWorkThreadProc(server *VIIDFeatureServer) {
	LogInfo(LOG_EVENT_ID_MOD_TOTAL_USER_COMBO, "TotalUserComboInfoWorkThreadProc start ...")
	for provider.totalUserComboThreadIsRunning {

		// 随机等待 0~6 分钟，避免多节点冲突
		randomMinutes := RedisRandomInRange(viidconf.TotalUserComboDiffTimeMinMinute, viidconf.TotalUserComboDiffTimeMaxMinute)
		time.Sleep(time.Duration(randomMinutes) * time.Minute)

		// 获取当前小时的开始和结束时间
		currentHourStart := GetCurrentHourStart()
		currentHourEnd := GetCurrentHourEnd()

		// 查询当前小时记录是否已经存在
		record_num, err := provider.Query_Hour_UserCombo_Record_Number(currentHourStart, currentHourEnd)
		if err != nil {
			LogError(LOG_EVENT_ID_MOD_TOTAL_USER_COMBO, utils.ERR_DB_QUERY_OPERATE_FAILED.Code, fmt.Sprintf("Query_Hour_UserCombo_Record_Number err = %v", err))
			continue
		}

		// 处理数据
		if record_num <= 0 {
			// 不存在则执行统计，逐个对象统计
			err := provider.Add_Hour_UserCombo_Record(VIID_Obj_Name_Person, currentHourStart, currentHourEnd)
			if err != nil {
				LogError(LOG_EVENT_ID_MOD_TOTAL_USER_COMBO, utils.ERR_DB_INSERT_OPERATE_FAILED.Code, fmt.Sprintf(
					"Add_Hour_UserCombo_Record %s err = %v", VIID_Obj_Name_Person, err))
			}
			err = provider.Add_Hour_UserCombo_Record(VIID_Obj_Name_Face, currentHourStart, currentHourEnd)
			if err != nil {
				LogError(LOG_EVENT_ID_MOD_TOTAL_USER_COMBO, utils.ERR_DB_INSERT_OPERATE_FAILED.Code, fmt.Sprintf(
					"Add_Hour_UserCombo_Record %s err = %v", VIID_Obj_Name_Face, err))
			}
			err = provider.Add_Hour_UserCombo_Record(VIID_Obj_Name_MotorVehicle, currentHourStart, currentHourEnd)
			if err != nil {
				LogError(LOG_EVENT_ID_MOD_TOTAL_USER_COMBO, utils.ERR_DB_INSERT_OPERATE_FAILED.Code, fmt.Sprintf(
					"Add_Hour_UserCombo_Record %s err = %v", VIID_Obj_Name_MotorVehicle, err))
			}
			err = provider.Add_Hour_UserCombo_Record(VIID_Obj_Name_NonMotorVehicle, currentHourStart, currentHourEnd)
			if err != nil {
				LogError(LOG_EVENT_ID_MOD_TOTAL_USER_COMBO, utils.ERR_DB_INSERT_OPERATE_FAILED.Code, fmt.Sprintf(
					"Add_Hour_UserCombo_Record %s err = %v", VIID_Obj_Name_NonMotorVehicle, err))
			}

			// 统计完成后，维护记录数
			provider.MaintainUserComboRecordNum()
		}

		// 等待到下一个小时 + 随机避让时间
		minutesToNextHour := GetMinutesToNextHour()
		randomWait := RedisRandomInRange(1, viidconf.TotalUserComboDiffTimeMaxMinute)
		totalWait := minutesToNextHour + randomWait

		LogInfo(LOG_EVENT_ID_MOD_TOTAL_USER_COMBO, fmt.Sprintf("TotalUserComboInfoWorkThreadProc wait %d minutes to next hour", totalWait))
		time.Sleep(time.Duration(totalWait) * time.Minute)
	}
	LogInfo(LOG_EVENT_ID_MOD_TOTAL_USER_COMBO, "TotalUserComboInfoWorkThreadProc end ...")
}

/*
 * @FuncName: 添加某小时用户套餐包的统计数据
 * @Version: v1.0.0
 * @Description: 数据库添加记录操作
 * @Param: object_type_name 对象类型名称
 * @Param: hourStart 小时开始时间
 * @Param: hourEnd 小时结束时间
 */
func (provider *MysqlProvider) Add_Hour_UserCombo_Record(object_type_name string, hourStart time.Time, hourEnd time.Time) error {

	// 获取所有用户和套餐包组合的统计
	// 查询当前小时内，按 UserID 和 StorageComboId 分组的统计数据
	userComboStats, err := provider.QueryTotal_UserCombo_Stats(object_type_name, hourStart, hourEnd)
	if err != nil {
		return err
	}

	// 表名称
	table_name := provider.getTableTypeName(&TTotalUserComboInfo{})

	// 遍历每个用户套餐包组合，插入统计记录
	for _, stat := range userComboStats {
		// 准备添加的记录
		var tTotalUserComboInfo TTotalUserComboInfo
		tTotalUserComboInfo.UserID = stat.UserID
		tTotalUserComboInfo.StorageComboId = stat.StorageComboId
		tTotalUserComboInfo.ObjectTypeName = object_type_name
		tTotalUserComboInfo.StartTime = hourStart
		tTotalUserComboInfo.EndTime = hourEnd
		tTotalUserComboInfo.DeviceViidNumber = stat.DeviceViidNumber
		tTotalUserComboInfo.ObjectNumber = stat.ObjectNumber

		// 获取文件统计信息
		fileNumber, fileSize, err := provider.QueryTotal_UserCombo_File_Stats(object_type_name, stat.UserID, stat.StorageComboId, hourStart, hourEnd)
		if err != nil {
			LogError(LOG_EVENT_ID_MOD_TOTAL_USER_COMBO, utils.ERR_DB_QUERY_OPERATE_FAILED.Code,
				fmt.Sprintf("QueryTotal_UserCombo_File_Stats %s %s %s err = %v", object_type_name, stat.UserID, stat.StorageComboId, err))
			continue
		}
		tTotalUserComboInfo.FileNumber = fileNumber
		tTotalUserComboInfo.FileTotalSize = fileSize

		// 查询记录是否已经存在（防止重复插入）
		existNum, err := provider.Query_Hour_UserCombo_Record_Exist(object_type_name, stat.UserID, stat.StorageComboId, hourStart, hourEnd)
		if err != nil {
			LogError(LOG_EVENT_ID_MOD_TOTAL_USER_COMBO, utils.ERR_DB_QUERY_OPERATE_FAILED.Code,
				fmt.Sprintf("Query_Hour_UserCombo_Record_Exist err = %v", err))
			continue
		}

		// 不存在则插入
		if existNum <= 0 {
			tx := provider.db.Table(table_name)
			if err := tx.Create(&tTotalUserComboInfo).Error; err != nil {
				LogError(LOG_EVENT_ID_MOD_TOTAL_USER_COMBO, utils.ERR_DB_INSERT_OPERATE_FAILED.Code,
					fmt.Sprintf("Add_Hour_UserCombo_Record %s %s %s %s-%s err:%v",
						object_type_name, stat.UserID, stat.StorageComboId, hourStart.Format("2006-01-02 15:04"), hourEnd.Format("15:04"), err))
				return err
			}
		}
	}

	return nil
}

/*
 * @FuncName: 查询某小时用户套餐包记录数
 * @Version: v1.0.0
 * @Description: 数据库查询操作
 * @Param: hourStart 小时开始时间
 * @Param: hourEnd 小时结束时间
 */
func (provider *MysqlProvider) Query_Hour_UserCombo_Record_Number(hourStart time.Time, hourEnd time.Time) (uint64, error) {

	// 返回值
	result_objs := uint64(0)

	// 表名称
	table_name := provider.getTableTypeName(&TTotalUserComboInfo{})

	// mysql语句
	str_total_sql := fmt.Sprintf("select count(ID) from %s where StartTime >= '%s' and EndTime <= '%s'",
		table_name, hourStart.Format(TIME_MYSQL_FMT), hourEnd.Format(TIME_MYSQL_FMT))

	raw_sql := provider.db.Raw(str_total_sql)
	if raw_sql != nil {
		if raw_sql.Error == nil {
			scan_sql := raw_sql.Scan(&result_objs)
			if scan_sql != nil {
				if scan_sql.Error != nil {
					LogError(LOG_EVENT_ID_MOD_TOTAL_USER_COMBO, utils.ERR_DB_QUERY_OPERATE_FAILED.Code,
						fmt.Sprintf("Query_Hour_UserCombo_Record_Number raw_sql.Scan(%s) err:%v", str_total_sql, scan_sql.Error))
					return result_objs, fmt.Errorf("Query_Hour_UserCombo_Record_Number raw_sql.Scan err:%v", scan_sql.Error)
				}
			} else {
				LogError(LOG_EVENT_ID_MOD_TOTAL_USER_COMBO, utils.ERR_DB_QUERY_OPERATE_FAILED.Code,
					fmt.Sprintf("Query_Hour_UserCombo_Record_Number raw_sql.Scan(%s) is Failed", str_total_sql))
			}
		} else {
			LogError(LOG_EVENT_ID_MOD_TOTAL_USER_COMBO, utils.ERR_DB_QUERY_OPERATE_FAILED.Code,
				fmt.Sprintf("Query_Hour_UserCombo_Record_Number db.Raw(%s) err:%v", str_total_sql, raw_sql.Error))
			return result_objs, fmt.Errorf("Query_Hour_UserCombo_Record_Number db.Raw err:%v", raw_sql.Error)
		}
	} else {
		LogError(LOG_EVENT_ID_MOD_TOTAL_USER_COMBO, utils.ERR_DB_QUERY_OPERATE_FAILED.Code,
			fmt.Sprintf("Query_Hour_UserCombo_Record_Number db.Raw(%s) is Failed", str_total_sql))
	}

	return result_objs, nil
}

