/*
 * @FuncName: 维护用户套餐包统计记录数
 * @Version: v1.0.0
 * @Description: 超过最大记录数时删除最早的记录
 * @Param: 无
 */
func (provider *MysqlProvider) MaintainUserComboRecordNum() {

	// 查询当前记录数
	totalNum, err := provider.QueryTotalUserComboRecordNum()
	if err != nil {
		LogError(LOG_EVENT_ID_MOD_TOTAL_USER_COMBO, utils.ERR_DB_QUERY_OPERATE_FAILED.Code,
			fmt.Sprintf("MaintainUserComboRecordNum QueryTotalUserComboRecordNum err = %v", err))
		return
	}

	// 超过阈值则删除
	if totalNum > uint64(viidconf.TotalUserComboMaxRecordNum) {
		deleteNum := viidconf.TotalUserComboDeleteRecordNum
		err := provider.DeleteOldestUserComboRecords(deleteNum)
		if err != nil {
			LogError(LOG_EVENT_ID_MOD_TOTAL_USER_COMBO, utils.ERR_DB_DELETE_OPERATE_FAILED.Code,
				fmt.Sprintf("MaintainUserComboRecordNum DeleteOldestUserComboRecords err = %v", err))
			return
		}

		LogInfo(LOG_EVENT_ID_MOD_TOTAL_USER_COMBO,
			fmt.Sprintf("MaintainUserComboRecordNum: deleted %d records, total was %d, max allowed %d",
				deleteNum, totalNum, viidconf.TotalUserComboMaxRecordNum))
	}
}

