/*
 * @FuncName: 删除最早的N条用户套餐包统计记录
 * @Version: v1.0.0
 * @Description: 数据库删除操作
 * @Param: deleteNum 删除记录数
 */
func (provider *MysqlProvider) DeleteOldestUserComboRecords(deleteNum int) error {

	// 表名称
	table_name := provider.getTableTypeName(&TTotalUserComboInfo{})

	// mysql语句 - 删除最早的N条记录
	str_delete_sql := fmt.Sprintf("DELETE FROM %s ORDER BY ID ASC LIMIT %d", table_name, deleteNum)

	result := provider.db.Exec(str_delete_sql)
	if result.Error != nil {
		LogError(LOG_EVENT_ID_MOD_TOTAL_USER_COMBO, utils.ERR_DB_DELETE_OPERATE_FAILED.Code,
			fmt.Sprintf("DeleteOldestUserComboRecords db.Exec(%s) err:%v", str_delete_sql, result.Error))
		return fmt.Errorf("DeleteOldestUserComboRecords db.Exec err:%v", result.Error)
	}

	LogInfo(LOG_EVENT_ID_MOD_TOTAL_USER_COMBO,
		fmt.Sprintf("DeleteOldestUserComboRecords: deleted %d rows", result.RowsAffected))

	return nil
}

/*
 * @FuncName: 计算当前时间到下一个小时的分钟数
 * @Version: v1.0.0
 * @Description: 计算到下一个小时0分的分钟数
 * @Param: 无
 */
func GetMinutesToNextHour() int {

	// 获取当前时间
	now := time.Now()

	// 计算下一个小时0分的时间
	nextHour := time.Date(
		now.Year(),
		now.Month(),
		now.Day(),
		now.Hour()+1, // 小时加1
		0,            // 分钟设为0
		0,            // 秒设为0
		0,            // 纳秒设为0
		now.Location(), // 使用当前时区
	)

	// 计算时间差（纳秒）
	duration := nextHour.Sub(now)

	// 转换为分钟并返回
	return int(duration.Minutes())
}

/*
 * @FuncName: 获取当前小时的开始时间
 * @Version: v1.0.0
 * @Description: 获取当前小时的开始时间（0分0秒）
 * @Param: 无
 */
func GetCurrentHourStart() time.Time {

	// 获取当前时间
	now := time.Now()

	// 当前小时的开始时间
	return time.Date(
		now.Year(),
		now.Month(),
		now.Day(),
		now.Hour(),
		0,
		0,
		0,
		now.Location(),
	)
}

/*
 * @FuncName: 获取当前小时的结束时间
 * @Version: v1.0.0
 * @Description: 获取当前小时的结束时间（59分59秒）
 * @Param: 无
 */
func GetCurrentHourEnd() time.Time {

	// 获取当前时间
	now := time.Now()

	// 当前小时的结束时间
	return time.Date(
		now.Year(),
		now.Month(),
		now.Day(),
		now.Hour(),
		59,
		59,
		0,
		now.Location(),
	)
}

