import (
	"fmt"
	"gopkgs/pkg/utils"
	"time"
)

/*
 * @FuncName: 查询某小时内所有用户套餐包组合的统计数据
 * @Version: v1.0.0
 * @Description: 数据库查询操作，按 UserID 和 StorageComboId 分组统计
 * @Param: object_type_name 对象类型名称
 * @Param: hourStart 小时开始时间
 * @Param: hourEnd 小时结束时间
 */
func (provider *MysqlProvider) QueryTotal_UserCombo_Stats(object_type_name string, hourStart time.Time, hourEnd time.Time) ([]UserComboStat, error) {

	// 返回值
	var result_stats []UserComboStat

	// 表名称
	table_name := ""

	// 对象处理
	switch object_type_name {
	case VIID_Obj_Name_Person:
		{
			table_name = provider.getTableTypeName(&TPersonCC{})
		}
	case VIID_Obj_Name_Face:
		{
			table_name = provider.getTableTypeName(&TFaceCC{})
		}
	case VIID_Obj_Name_MotorVehicle:
		{
			table_name = provider.getTableTypeName(&TMotorVehicleCC{})
		}
	case VIID_Obj_Name_NonMotorVehicle:
		{
			table_name = provider.getTableTypeName(&TNonMotorVehicleCC{})
		}
	default:
		{
			return result_stats, nil
		}
	}

	// 格式化时间
	strHourStart := hourStart.Format(TIME_MYSQL_FMT)
	strHourEnd := hourEnd.Format(TIME_MYSQL_FMT)

	// 生产mysql统计，子语句 - 每个分表查询该小时内按UserID和StorageComboId分组的设备数和对象数
	str_total_sub_sql := []string{}
	for i := 0; i < viidconf.TableNumber; i++ {
		str_total_current_sub_sql := fmt.Sprintf(
			" select UserID, StorageComboId, count(distinct(ViidID)) as device_num, count(ID) as object_num from %s_%d where CreatedAt >= '%s' and CreatedAt <= '%s' group by UserID, StorageComboId ",
			table_name, i, strHourStart, strHourEnd)
		str_total_sub_sql = append(str_total_sub_sql, str_total_current_sub_sql)
	}

	// 组装mysql统计，语句 - 使用 UNION ALL 合并所有分表结果
	str_total_sql := "select UserID, StorageComboId, sum(device_num) as total_device_num, sum(object_num) as total_object_num from ( "
	for i := 0; i < len(str_total_sub_sql); i++ {
		str_total_sql += str_total_sub_sql[i]
		if !((i + 1) == len(str_total_sub_sql)) {
			str_total_sql += " union all "
		}
	}
	str_total_sql += " ) as combined group by UserID, StorageComboId"

	/*
		在Golang的GORM库中，使用DB.Raw()和DB.Exec()进行SQL原生语句操作的区别。
		DB.Raw()适用于查询并映射到结构体，返回*sql.Rows结果集；
		而DB.Exec()用于增删改，返回*sql.Result，不涉及结果映射。
		两者都需要关注SQL注入和预检查操作。
	*/
	raw_sql := provider.db.Raw(str_total_sql)
	if raw_sql != nil {
		if raw_sql.Error == nil {
			rows, err := raw_sql.Rows()
			if err != nil {
				LogError(LOG_EVENT_ID_MOD_TOTAL_USER_COMBO, utils.ERR_DB_QUERY_OPERATE_FAILED.Code,
					fmt.Sprintf("QueryTotal_UserCombo_Stats raw_sql.Rows(%s) err:%v", str_total_sql, err))
				return result_stats, fmt.Errorf("QueryTotal_UserCombo_Stats raw_sql.Rows err:%v", err)
			}
			defer rows.Close()

			for rows.Next() {
				var stat UserComboStat
				if err := rows.Scan(&stat.UserID, &stat.StorageComboId, &stat.DeviceViidNumber, &stat.ObjectNumber); err != nil {
					LogError(LOG_EVENT_ID_MOD_TOTAL_USER_COMBO, utils.ERR_DB_QUERY_OPERATE_FAILED.Code,
						fmt.Sprintf("QueryTotal_UserCombo_Stats rows.Scan err:%v", err))
					continue
				}
				result_stats = append(result_stats, stat)
			}
		} else {
			// 返回sql错误信息
			LogError(LOG_EVENT_ID_MOD_TOTAL_USER_COMBO, utils.ERR_DB_QUERY_OPERATE_FAILED.Code,
				fmt.Sprintf("QueryTotal_UserCombo_Stats db.Raw(%s) err:%v", str_total_sql, raw_sql.Error))
			return result_stats, fmt.Errorf("QueryTotal_UserCombo_Stats db.Raw err:%v", raw_sql.Error)
		}
	} else {
		LogError(LOG_EVENT_ID_MOD_TOTAL_USER_COMBO, utils.ERR_DB_QUERY_OPERATE_FAILED.Code,
			fmt.Sprintf("QueryTotal_UserCombo_Stats db.Raw(%s) is Failed", str_total_sql))
	}

	return result_stats, nil
}

