		randomIndex := RedisRandomInRange(0, 10)
		randomMinutes := randomIndex * 6
		time.Sleep(time.Duration(randomMinutes) * time.Minute)

		// 获取上一个小时的整点时间范围
		// 例如：当前 10:30，统计 9:00-10:00 的数据
		lastHourStart := GetLastHourStart()
		lastHourEnd := GetLastHourEnd()

		LogInfo(LOG_EVENT_ID_MOD_TOTAL_USER_COMBO, fmt.Sprintf("TotalUserComboInfoWorkThreadProc stat period: %s ~ %s",
			lastHourStart.Format("2006-01-02 15:04"), lastHourEnd.Format("2006-01-02 15:04")))

		// 查询上一个小时记录是否已经存在
		record_num, err := provider.Query_Hour_UserCombo_Record_Number(lastHourStart, lastHourEnd)
		if err != nil {
			LogError(LOG_EVENT_ID_MOD_TOTAL_USER_COMBO, utils.ERR_DB_QUERY_OPERATE_FAILED.Code, fmt.Sprintf("Query_Hour_UserCombo_Record_Number err = %v", err))
			continue
		}

		// 处理数据
