			if err != nil {
				LogError(LOG_EVENT_ID_MOD_TOTAL_USER_COMBO, utils.ERR_DB_INSERT_OPERATE_FAILED.Code, fmt.Sprintf(
					"Add_Hour_UserCombo_Record %s err = %v", VIID_Obj_Name_Person, err))
			}
			err = provider.Add_Hour_UserCombo_Record(VIID_Obj_Name_Face, lastHourStart, lastHourEnd)
			if err != nil {
				LogError(LOG_EVENT_ID_MOD_TOTAL_USER_COMBO, utils.ERR_DB_INSERT_OPERATE_FAILED.Code, fmt.Sprintf(
					"Add_Hour_UserCombo_Record %s err = %v", VIID_Obj_Name_Face, err))
