{"filePath":"/Users/dev02/Desktop/1400Project/gat1400dbserver/mysql_total_user_combo_info.go","newString":"/*
 * @FuncName: 计算当前时间到下一个小时的分钟数
 * @Version: v1.0.0
 * @Description: 计算到下一个小时0分的分钟数
 * @Param: 无
 */
func GetMinutesToNextHour() int {

	// 获取当前时间
	now := time.Now()

	// 计算下一个小时0分的时间
	nextHour := time.Date(
		now.Year(),
		now.Month(),
		now.Day(),
		now.Hour()+1, // 小时加1
		0,            // 分钟设为0
		0,            // 秒设为0
		0,            // 纳秒设为0
		now.Location(), // 使用当前时区
	)

	// 计算时间差（纳秒）
	duration := nextHour.Sub(now)

	// 转换为分钟并返回
	return int(duration.Minutes())
}

