{"filePath":"/Users/dev02/Desktop/1400Project/gat1400dbserver/mysql_total_user_combo_info.go","newString":"func (provider *MysqlProvider) TotalUserComboInfoWorkThreadProc(server *VIIDFeatureServer) {
	LogInfo(LOG_EVENT_ID_MOD_TOTAL_USER_COMBO, "TotalUserComboInfoWorkThreadProc start ...")
	for provider.totalUserComboThreadIsRunning {

		// 随机等待，间隔6分钟：0, 6, 12, 18, 24, 30, 36, 42, 48, 54, 60 分钟
		// 生成 0~10 的随机索引，然后乘以6得到分钟数
		randomIndex := RedisRandomInRange(0, 10)
		randomMinutes := randomIndex * 6
		time.Sleep(time.Duration(randomMinutes) * time.Minute)

		// 获取上一个小时的整点时间范围
		// 例如：当前 10:30，统计 9:00-10:00 的数据
		lastHourStart := GetLastHourStart()
		lastHourEnd := GetLastHourEnd()

		LogInfo(LOG_EVENT_ID_MOD_TOTAL_USER_COMBO, fmt.Sprintf("TotalUserComboInfoWorkThreadProc stat period: %s ~ %s",
			lastHourStart.Format("2006-01-02 15:04"), lastHourEnd.Format("2006-01-02 15:04")))

		// 逐个对象类型统计，每个对象独立检查是否存在
		// 这样即使服务A统计了Person，服务B仍然可以统计Face、MotorVehicle、NonMotorVehicle
		objectTypes := []string{VIID_Obj_Name_Person, VIID_Obj_Name_Face, VIID_Obj_Name_MotorVehicle, VIID_Obj_Name_NonMotorVehicle}

		for _, objectType := range objectTypes {
			// 检查该对象类型在当前时间段是否已有记录
			recordNum, err := provider.Query_ObjectType_Hour_Record_Number(objectType, lastHourStart, lastHourEnd)
			if err != nil {
				LogError(LOG_EVENT_ID_MOD_TOTAL_USER_COMBO, utils.ERR_DB_QUERY_OPERATE_FAILED.Code, 
					fmt.Sprintf("Query_ObjectType_Hour_Record_Number %s err = %v", objectType, err))
				continue
			}

			// 如果该对象类型已有记录，跳过
			if recordNum > 0 {
				LogInfo(LOG_EVENT_ID_MOD_TOTAL_USER_COMBO, fmt.Sprintf("TotalUserComboInfoWorkThreadProc %s already has %d records, skip", objectType, recordNum))
				continue
			}

			// 执行统计
			err = provider.Add_Hour_UserCombo_Record(objectType, lastHourStart, lastHourEnd)
			if err != nil {
				LogError(LOG_EVENT_ID_MOD_TOTAL_USER_COMBO, utils.ERR_DB_INSERT_OPERATE_FAILED.Code, fmt.Sprintf(
					"Add_Hour_UserCombo_Record %s err = %v", objectType, err))
			}
		}

		// 统计完成后，维护记录数
		provider.MaintainUserComboRecordNum()

		// 等待到下一个整点 + 随机避让时间（间隔6分钟）
		// 例如：当前 10:30，等待到 11:00 + 随机避让
		minutesToNextHour := GetMinutesToNextHour()
		randomWaitIndex := RedisRandomInRange(1, 10) // 1~10，避免0
		randomWait := randomWaitIndex * 6              // 6, 12, 18, ..., 60 分钟
		totalWait := minutesToNextHour + randomWait

		LogInfo(LOG_EVENT_ID_MOD_TOTAL_USER_COMBO, fmt.Sprintf("TotalUserComboInfoWorkThreadProc wait %d minutes (to next hour: %d, random avoid: %d)",
			totalWait, minutesToNextHour, randomWait))
		time.Sleep(time.Duration(totalWait) * time.Minute)
	}
	LogInfo(LOG_EVENT_ID_MOD_TOTAL_USER_COMBO, "TotalUserComboInfoWorkThreadProc end ...")
}","oldString":"func (provider *MysqlProvider) TotalUserComboInfoWorkThreadProc(server *VIIDFeatureServer) {
