{"content":"package main

import (
	"fmt"
	"gopkgs/pkg/utils"
	"time"
)

/*
 * @StructName: 套餐包聚合统计结果（阶段1 输出）
 * @Version: v1.0.0
 * @Description: 按 StorageComboId 聚合的统计数据，不包含 UserID
 */
type ComboStat struct {
	StorageComboId   string // 套餐包ID（NULL 转换为空字符串）
	DeviceViidNumber uint64 // 活跃设备数
	ObjectNumber     uint64 // 对象个数
	LastRecordID     uint64 // 该套餐包在该小时内的最后一条记录ID（用于阶段3反查UserID）
}

/*
 * @FuncName: [阶段1] 按套餐包聚合统计（不查询 UserID）
 * @Version: v1.0.0
 * @Description: 数据库查询操作，按 StorageComboId 分组统计活跃设备数和对象数
 *               使用 COALESCE 处理 NULL，性能优于按 UserID+StorageComboId 分组
 * @Param: object_type_name 对象类型名称
 * @Param: hourStart 小时开始时间（整点）
 * @Param: hourEnd 小时结束时间（整点）
 */
func (provider *MysqlProvider) QueryTotal_Combo_Stats(object_type_name string, hourStart time.Time, hourEnd time.Time) ([]ComboStat, error) {

	// 返回值
	var result_stats []ComboStat

	// 表名称
	table_name := ""

	// 对象处理
	switch object_type_name {
	case VIID_Obj_Name_Person:
		{
			table_name = provider.getTableTypeName(&TPersonCC{})
		}
	case VIID_Obj_Name_Face:
		{
			table_name = provider.getTableTypeName(&TFaceCC{})
		}
	case VIID_Obj_Name_MotorVehicle:
		{
			table_name = provider.getTableTypeName(&TMotorVehicleCC{})
		}
