			subimage_table_name = provider.getTableTypeName(&TNonMotorVehicleSubImage{})
			object_id_name = "NonMotorVehicleID"
		}
	default:
		{
			return fileNumber, fileSize, nil
		}
	}

	// 格式化时间
	strHourStart := hourStart.Format(TIME_MYSQL_FMT)
	strHourEnd := hourEnd.Format(TIME_MYSQL_FMT)

	// 转义套餐包ID（防止 SQL 注入和特殊字符问题）
	safeStorageComboId := escapeSQLString(storageComboId)

	// 子语句 - 每个分表查询该套餐包在该小时内的文件数和文件大小
	// 使用 COALESCE 处理 NULL 的 StorageComboId
	// 子图表（SubImage表）的 StorageComboId 字段在历史数据中可能为 NULL，但本查询不读取该字段，仅通过 CC表的 ID 关联
	str_total_sub_sql := []string{}
	for i := 0; i < viidconf.TableNumber; i++ {
		str_total_current_sub_sql := fmt.Sprintf(
			" select count(ID) as file_num, coalesce(sum(FileSize),0) as file_size from %s_%d where %s in (select %s from %s_%d where COALESCE(StorageComboId, '') = '%s' and CreatedAt >= '%s' and CreatedAt <= '%s') ",
			subimage_table_name, i, object_id_name, object_id_name, cc_table_name, i, safeStorageComboId, strHourStart, strHourEnd)
