	for i := 0; i < len(str_total_sub_sql); i++ {
		str_total_sql += str_total_sub_sql[i]
		if !((i + 1) == len(str_total_sub_sql)) {
			str_total_sql += " union all "
		}
	}
	str_total_sql += " ) as combined"

	raw_sql := provider.db.Raw(str_total_sql)
	if raw_sql == nil {
		LogError(LOG_EVENT_ID_MOD_TOTAL_USER_COMBO, utils.ERR_DB_QUERY_OPERATE_FAILED.Code,
			"QueryTotal_Combo_File_Stats db.Raw is Failed")
		return fileNumber, fileSize, nil
	}

	if raw_sql.Error != nil {
		// 错误处理：返回 0 值而不是错误，避免影响整体统计流程
		LogError(LOG_EVENT_ID_MOD_TOTAL_USER_COMBO, utils.ERR_DB_QUERY_OPERATE_FAILED.Code,
			fmt.Sprintf("QueryTotal_Combo_File_Stats db.Raw err:%v (storageComboId=%s)", raw_sql.Error, storageComboId))
		return fileNumber, fileSize, nil
	}

	rows, err := raw_sql.Rows()
	if err != nil {
		LogError(LOG_EVENT_ID_MOD_TOTAL_USER_COMBO, utils.ERR_DB_QUERY_OPERATE_FAILED.Code,
			fmt.Sprintf("QueryTotal_Combo_File_Stats raw_sql.Rows err:%v", err))
		return fileNumber, fileSize, nil
	}
	defer rows.Close()

	if rows.Next() {
		if scanErr := rows.Scan(&fileNumber, &fileSize); scanErr != nil {
			// 扫描错误：返回 0 值
			LogError(LOG_EVENT_ID_MOD_TOTAL_USER_COMBO, utils.ERR_DB_QUERY_OPERATE_FAILED.Code,
				fmt.Sprintf("QueryTotal_Combo_File_Stats rows.Scan err:%v (storageComboId=%s)", scanErr, storageComboId))
			return uint64(0), uint64(0), nil
		}
	}

	return fileNumber, fileSize, nil
