/*
 * @FuncName: 转义 SQL 字符串中的特殊字符
 * @Version: v1.0.0
 * @Description: 防止 SQL 注入和特殊字符问题（例如存储套餐包ID中的单引号）
 * @Param: s 原始字符串
 * @Return: 转义后的字符串
 */
func escapeSQLString(s string) string {
	// 转义单引号、反斜杠等特殊字符
	result := ""
	for _, c := range s {
		switch c {
		case '\'':
			result += "\\'"
		case '"':
			result += "\\\""
		case '\\':
			result += "\\\\"
		case '\n':
			result += "\\n"
		case '\r':
			result += "\\r"
		case '\x00':
			result += "\\0"
		default:
			result += string(c)
		}
	}
	return result
}"}

