	// 阶段4: 组装完整记录并保存
	insertedCount := 0
	skippedCount := 0
	emptyComboCount := 0 // 空套餐包ID的数量（兼容历史数据）

	for _, stat := range comboStats {
		// 防御性检查：套餐包ID 可能为空字符串（历史数据 NULL 转换）
		comboID := stat.StorageComboId
		if len(comboID) == 0 {
			emptyComboCount++
		}

		// 获取套餐包对应的 last_id 和 UserID
		lastID, hasLastID := comboLastIDs[stat.StorageComboId]
		if !hasLastID {
			LogWarn(LOG_EVENT_ID_MOD_TOTAL_USER_COMBO,
				fmt.Sprintf("Add_Hour_UserCombo_Record %s combo '%s' no last id found",
					object_type_name, stat.StorageComboId))
			continue
		}
		userID, hasUser := idToUser[lastID]
		if !hasUser {
			LogWarn(LOG_EVENT_ID_MOD_TOTAL_USER_COMBO,
				fmt.Sprintf("Add_Hour_UserCombo_Record %s combo '%s' id %d no user found",
					object_type_name, stat.StorageComboId, lastID))
			continue
		}

		// 查询记录是否已存在（防止重复插入）
		existNum, err := provider.Query_Hour_UserCombo_Record_Exist(object_type_name, userID, stat.StorageComboId, hourStart, hourEnd)
		if err != nil {
			LogError(LOG_EVENT_ID_MOD_TOTAL_USER_COMBO, utils.ERR_DB_QUERY_OPERATE_FAILED.Code,
				fmt.Sprintf("Query_Hour_UserCombo_Record_Exist %s %s '%s' err = %v",
					object_type_name, userID, stat.StorageComboId, err))
			continue
		}

		// 已存在则跳过
		if existNum > 0 {
			skippedCount++
			continue
		}

		// 查询文件统计
		fileNumber, fileSize, err := provider.QueryTotal_Combo_File_Stats(object_type_name, stat.StorageComboId, hourStart, hourEnd)
		if err != nil {
			LogError(LOG_EVENT_ID_MOD_TOTAL_USER_COMBO, utils.ERR_DB_QUERY_OPERATE_FAILED.Code,
				fmt.Sprintf("QueryTotal_Combo_File_Stats %s '%s' err = %v",
					object_type_name, stat.StorageComboId, err))
			continue
		}

		// 组装并插入记录
		var tTotalUserComboInfo TTotalUserComboInfo
		tTotalUserComboInfo.UserID = userID
		tTotalUserComboInfo.StorageComboId = stat.StorageComboId
		tTotalUserComboInfo.ObjectTypeName = object_type_name
		tTotalUserComboInfo.StartTime = hourStart
		tTotalUserComboInfo.EndTime = hourEnd
		tTotalUserComboInfo.DeviceViidNumber = stat.DeviceViidNumber
		tTotalUserComboInfo.ObjectNumber = stat.ObjectNumber
		tTotalUserComboInfo.FileNumber = fileNumber
		tTotalUserComboInfo.FileTotalSize = fileSize

		tx := provider.db.Table(table_name)
		if err := tx.Create(&tTotalUserComboInfo).Error; err != nil {
			LogError(LOG_EVENT_ID_MOD_TOTAL_USER_COMBO, utils.ERR_DB_INSERT_OPERATE_FAILED.Code,
				fmt.Sprintf("Add_Hour_UserCombo_Record %s %s '%s' %s-%s err:%v",
					object_type_name, userID, stat.StorageComboId,
					hourStart.Format("15:04"), hourEnd.Format("15:04"), err))
			continue
		}
		insertedCount++
	}

	LogInfo(LOG_EVENT_ID_MOD_TOTAL_USER_COMBO,
		fmt.Sprintf("Add_Hour_UserCombo_Record %s %s-%s: combos=%d inserted=%d skipped=%d empty=%d",
			object_type_name,
			hourStart.Format("15:04"), hourEnd.Format("15:04"),
			len(comboStats), insertedCount, skippedCount, emptyComboCount))

	return nil
}"}

