/*
 * @FuncName: 安全复制 StorageComboId 指针
 * @Version: v1.0.0
 * @Description: 向后兼容：requestData.StorageComboId 可能为 nil（历史数据或可选字段）
 *               此函数确保不会出现空指针解引用，统一处理 NULL 值
 * @Param: src 源 *string 指针（可能为 nil）
 * @Return: dst 目标 *string 指针（可能为 nil，表示无套餐包）
 */
func SafeCopyStorageComboId(src *string) *string {
	// 防御性检查：避免空指针解引用
	if src == nil {
		return nil
	}
	// 创建副本，避免后续修改影响原始值
	value := *src
	return &value
}

/*
 * @FuncName: 安全获取 StorageComboId 字符串值
