{"filePath":"/Users/dev02/Desktop/1400Project/gat1400dbserver/mysql_total_user_combo_info.go","oldString":"/*
 * @FuncName: 添加某小时用户套餐包的统计数据（三阶段聚合）
 * @Version: v1.0.0
 * @Description: 数据库添加记录操作
 *               阶段1: 按套餐包聚合统计（device_num, object_num），不查询 UserID
 *               阶段2: 按套餐包查询最后记录ID（MAX(ID)）
 *               阶段3: 通过 last_id 批量反查 UserID
 *               然后组装完整记录并保存
 *
 * 向后兼容说明：
 *   1. 历史数据 StorageComboId 可能为 NULL，使用 COALESCE 转为空字符串
 *   2. 空字符串套餐包视为"无套餐包"，归为一类统计
 *   3. 子图表（SubImage）的 StorageComboId NULL 不影响查询（不读取该字段）
 *   4. 所有错误均有日志和保护性处理，不会导致程序崩溃
 * @Param: object_type_name 对象类型名称
 * @Param: hourStart 小时开始时间（整点）
 * @Param: hourEnd 小时结束时间（整点）
 */
func (provider *MysqlProvider) Add_Hour_UserCombo_Record(object_type_name string, hourStart time.Time, hourEnd time.Time) error {

	// 阶段1: 按套餐包聚合统计（不查询 UserID）
	comboStats, err := provider.QueryTotal_Combo_Stats(object_type_name, hourStart, hourEnd)
	if err != nil {
		LogError(LOG_EVENT_ID_MOD_TOTAL_USER_COMBO, utils.ERR_DB_QUERY_OPERATE_FAILED.Code,
			fmt.Sprintf("QueryTotal_Combo_Stats %s err = %v", object_type_name, err))
		return err
	}

	// 没有数据则直接返回
	if len(comboStats) == 0 {
		LogInfo(LOG_EVENT_ID_MOD_TOTAL_USER_COMBO,
			fmt.Sprintf("Add_Hour_UserCombo_Record %s %s-%s no combo stats found",
				object_type_name, hourStart.Format("15:04"), hourEnd.Format("15:04")))
		return nil
	}

	// 阶段2: 按套餐包查询最后记录ID
	comboLastIDs, err := provider.QueryTotal_Combo_LastRecordID(object_type_name, hourStart, hourEnd)
	if err != nil {
		LogError(LOG_EVENT_ID_MOD_TOTAL_USER_COMBO, utils.ERR_DB_QUERY_OPERATE_FAILED.Code,
			fmt.Sprintf("QueryTotal_Combo_LastRecordID %s err = %v", object_type_name, err))
		return err
	}

	// 阶段3: 收集所有 last_id，批量反查 UserID
	recordIDList := make([]uint64, 0, len(comboStats))
	for _, stat := range comboStats {
		if lastID, ok := comboLastIDs[stat.StorageComboId]; ok {
			recordIDList = append(recordIDList, lastID)
		}
	}

	idToUser, err := provider.QueryTotal_UserID_ByRecordIDs(object_type_name, recordIDList)
	if err != nil {
		LogError(LOG_EVENT_ID_MOD_TOTAL_USER_COMBO, utils.ERR_DB_QUERY_OPERATE_FAILED.Code,
			fmt.Sprintf("QueryTotal_UserID_ByRecordIDs %s err = %v", object_type_name, err))
		return err
	}

	// 表名称
	table_name := provider.getTableTypeName(&TTotalUserComboInfo{})

	// 阶段4: 组装完整记录并保存
	insertedCount := 0
	skippedCount := 0
	emptyComboCount := 0 // 空套餐包ID的数量（兼容历史数据）

	for _, stat := range comboStats {
		// 防御性检查：套餐包ID 可能为空字符串（历史数据 NULL 转换）
		comboID := stat.StorageComboId
		if len(comboID) == 0 {
			emptyComboCount++
		}

		// 获取套餐包对应的 last_id 和 UserID
		lastID, hasLastID := comboLastIDs[stat.StorageComboId]
		if !hasLastID {
			LogWarn(LOG_EVENT_ID_MOD_TOTAL_USER_COMBO,
				fmt.Sprintf("Add_Hour_UserCombo_Record %s combo '%s' no last id found",
					object_type_name, stat.StorageComboId))
			continue
		}
		userID, hasUser := idToUser[lastID]
		if !hasUser {
			LogWarn(LOG_EVENT_ID_MOD_TOTAL_USER_COMBO,
				fmt.Sprintf("Add_Hour_UserCombo_Record %s combo '%s' id %d no user found",
					object_type_name, stat.StorageComboId, lastID))
			continue
		}

		// 查询记录是否已存在（防止重复插入）
		existNum, err := provider.Query_Hour_UserCombo_Record_Exist(object_type_name, userID, stat.StorageComboId, hourStart, hourEnd)
		if err != nil {
			LogError(LOG_EVENT_ID_MOD_TOTAL_USER_COMBO, utils.ERR_DB_QUERY_OPERATE_FAILED.Code,
				fmt.Sprintf("Query_Hour_UserCombo_Record_Exist %s %s '%s' err = %v",
					object_type_name, userID, stat.StorageComboId, err))
			continue
		}

		// 已存在则跳过
		if existNum > 0 {
			skippedCount++
			continue
		}

		// 查询文件统计
		fileNumber, fileSize, err := provider.QueryTotal_Combo_File_Stats(object_type_name, stat.StorageComboId, hourStart, hourEnd)
		if err != nil {
			LogError(LOG_EVENT_ID_MOD_TOTAL_USER_COMBO, utils.ERR_DB_QUERY_OPERATE_FAILED.Code,
				fmt.Sprintf("QueryTotal_Combo_File_Stats %s '%s' err = %v",
					object_type_name, stat.StorageComboId, err))
			continue
		}

		// 组装并插入记录
		var tTotalUserComboInfo TTotalUserComboInfo
		tTotalUserComboInfo.UserID = userID
		tTotalUserComboInfo.StorageComboId = stat.StorageComboId
		tTotalUserComboInfo.ObjectTypeName = object_type_name
		tTotalUserComboInfo.StartTime = hourStart
		tTotalUserComboInfo.EndTime = hourEnd
		tTotalUserComboInfo.DeviceViidNumber = stat.DeviceViidNumber
		tTotalUserComboInfo.ObjectNumber = stat.ObjectNumber
		tTotalUserComboInfo.FileNumber = fileNumber
		tTotalUserComboInfo.FileTotalSize = fileSize

		tx := provider.db.Table(table_name)
		if err := tx.Create(&tTotalUserComboInfo).Error; err != nil {
			LogError(LOG_EVENT_ID_MOD_TOTAL_USER_COMBO, utils.ERR_DB_INSERT_OPERATE_FAILED.Code,
				fmt.Sprintf("Add_Hour_UserCombo_Record %s %s '%s' %s-%s err:%v",
					object_type_name, userID, stat.StorageComboId,
					hourStart.Format("15:04"), hourEnd.Format("15:04"), err))
			continue
		}
		insertedCount++
	}

	LogInfo(LOG_EVENT_ID_MOD_TOTAL_USER_COMBO,
		fmt.Sprintf("Add_Hour_UserCombo_Record %s %s-%s: combos=%d inserted=%d skipped=%d empty=%d",
			object_type_name,
			hourStart.Format("15:04"), hourEnd.Format("15:04"),
			len(comboStats), insertedCount, skippedCount, emptyComboCount))

	return nil
}","newString":"/*
 * @FuncName: 添加某小时用户套餐包的统计数据（三阶段聚合）
 * @Version: v1.0.0
 * @Description: 数据库添加记录操作
 *               阶段1: 按套餐包聚合统计（device_num, object_num），不查询 UserID
 *               阶段2: 按套餐包查询最后记录ID（MAX(ID)）
 *               阶段3: 通过 last_id 批量反查 UserID
 *               然后组装完整记录并保存
 *
 * 向后兼容说明：
 *   1. 历史数据 StorageComboId 可能为 NULL，使用 COALESCE 转为空字符串
 *   2. 空字符串套餐包视为"无套餐包"，归为一类统计
 *   3. 子图表（SubImage）的 StorageComboId NULL 不影响查询（不读取该字段）
 *   4. 所有错误均有日志和保护性处理，不会导致程序崩溃
 *   5. **统计数据为 0 也要保存**：用于多节点并发避让机制
 *      - 即使 device_num=0, object_num=0 也要插入
 *      - 即使完全无数据也要插入一条"占位"记录（所有字段=0）
 *      - 这样其他服务检查到记录存在就会跳过，避免重复统计
 * @Param: object_type_name 对象类型名称
 * @Param: hourStart 小时开始时间（整点）
 * @Param: hourEnd 小时结束时间（整点）
 */
func (provider *MysqlProvider) Add_Hour_UserCombo_Record(object_type_name string, hourStart time.Time, hourEnd time.Time) error {

	// 阶段1: 按套餐包聚合统计（不查询 UserID）
	comboStats, err := provider.QueryTotal_Combo_Stats(object_type_name, hourStart, hourEnd)
	if err != nil {
		LogError(LOG_EVENT_ID_MOD_TOTAL_USER_COMBO, utils.ERR_DB_QUERY_OPERATE_FAILED.Code,
			fmt.Sprintf("QueryTotal_Combo_Stats %s err = %v", object_type_name, err))
		return err
	}

	// **向后兼容**：完全没有数据时，也要插入一条"占位"记录（所有数据=0）
	// 这样其他服务检查到有记录就会跳过，避免重复统计（避让机制）
	if len(comboStats) == 0 {
		LogInfo(LOG_EVENT_ID_MOD_TOTAL_USER_COMBO,
			fmt.Sprintf("Add_Hour_UserCombo_Record %s %s-%s no combo stats, inserting placeholder for avoidance",
				object_type_name, hourStart.Format("15:04"), hourEnd.Format("15:04")))
		return provider.insertPlaceholderRecord(object_type_name, hourStart, hourEnd)
	}

	// 阶段2: 按套餐包查询最后记录ID
	comboLastIDs, err := provider.QueryTotal_Combo_LastRecordID(object_type_name, hourStart, hourEnd)
	if err != nil {
		LogError(LOG_EVENT_ID_MOD_TOTAL_USER_COMBO, utils.ERR_DB_QUERY_OPERATE_FAILED.Code,
			fmt.Sprintf("QueryTotal_Combo_LastRecordID %s err = %v", object_type_name, err))
		return err
	}

	// 阶段3: 收集所有 last_id，批量反查 UserID
	recordIDList := make([]uint64, 0, len(comboStats))
	for _, stat := range comboStats {
		if lastID, ok := comboLastIDs[stat.StorageComboId]; ok {
			recordIDList = append(recordIDList, lastID)
		}
	}

	idToUser, err := provider.QueryTotal_UserID_ByRecordIDs(object_type_name, recordIDList)
	if err != nil {
		LogError(LOG_EVENT_ID_MOD_TOTAL_USER_COMBO, utils.ERR_DB_QUERY_OPERATE_FAILED.Code,
			fmt.Sprintf("QueryTotal_UserID_ByRecordIDs %s err = %v", object_type_name, err))
		return err
	}

	// 表名称
	table_name := provider.getTableTypeName(&TTotalUserComboInfo{})

	// 阶段4: 组装完整记录并保存
	insertedCount := 0
	skippedCount := 0
	emptyComboCount := 0    // 空套餐包ID的数量（兼容历史数据）
	zeroStatCount := 0      // 统计数据全为 0 的套餐包数量
	missingUserIDCount := 0 // UserID 未反查到的数量（防御性插入）

	for _, stat := range comboStats {
		// 防御性检查：套餐包ID 可能为空字符串（历史数据 NULL 转换）
		comboID := stat.StorageComboId
		if len(comboID) == 0 {
			emptyComboCount++
		}

		// **向后兼容**：统计数据全为 0 也要计数
		if stat.DeviceViidNumber == 0 && stat.ObjectNumber == 0 {
			zeroStatCount++
		}

		// 获取套餐包对应的 last_id 和 UserID
		// **向后兼容**：即使未找到，也使用 0 值不阻塞插入
		lastID, hasLastID := comboLastIDs[stat.StorageComboId]
		if !hasLastID {
			LogWarn(LOG_EVENT_ID_MOD_TOTAL_USER_COMBO,
				fmt.Sprintf("Add_Hour_UserCombo_Record %s combo '%s' no last id found, use 0",
					object_type_name, stat.StorageComboId))
			lastID = 0
		}

		// **向后兼容**：UserID 未反查到时使用空字符串（不阻塞插入）
		userID, hasUser := idToUser[lastID]
		if !hasUser {
			LogWarn(LOG_EVENT_ID_MOD_TOTAL_USER_COMBO,
				fmt.Sprintf("Add_Hour_UserCombo_Record %s combo '%s' id %d no user found, use empty",
					object_type_name, stat.StorageComboId, lastID))
			userID = ""
			missingUserIDCount++
		}

		// 查询记录是否已存在（防止重复插入）
		existNum, err := provider.Query_Hour_UserCombo_Record_Exist(object_type_name, userID, stat.StorageComboId, hourStart, hourEnd)
		if err != nil {
			LogError(LOG_EVENT_ID_MOD_TOTAL_USER_COMBO, utils.ERR_DB_QUERY_OPERATE_FAILED.Code,
				fmt.Sprintf("Query_Hour_UserCombo_Record_Exist %s %s '%s' err = %v",
					object_type_name, userID, stat.StorageComboId, err))
			continue
		}

		// 已存在则跳过
		if existNum > 0 {
			skippedCount++
			continue
		}

		// 查询文件统计（失败也使用 0 值，不阻塞插入）
		// **向后兼容**：文件统计失败也保存（值为 0）
		fileNumber, fileSize, fileErr := provider.QueryTotal_Combo_File_Stats(object_type_name, stat.StorageComboId, hourStart, hourEnd)
		if fileErr != nil {
			LogWarn(LOG_EVENT_ID_MOD_TOTAL_USER_COMBO,
				fmt.Sprintf("Add_Hour_UserCombo_Record %s '%s' QueryTotal_Combo_File_Stats err: %v, use 0",
					object_type_name, stat.StorageComboId, fileErr))
			fileNumber = 0
			fileSize = 0
		}

		// 组装并插入记录（即使数据全部为 0 也要保存）
		var tTotalUserComboInfo TTotalUserComboInfo
		tTotalUserComboInfo.UserID = userID
		tTotalUserComboInfo.StorageComboId = stat.StorageComboId
		tTotalUserComboInfo.ObjectTypeName = object_type_name
		tTotalUserComboInfo.StartTime = hourStart
		tTotalUserComboInfo.EndTime = hourEnd
		tTotalUserComboInfo.DeviceViidNumber = stat.DeviceViidNumber
		tTotalUserComboInfo.ObjectNumber = stat.ObjectNumber
		tTotalUserComboInfo.FileNumber = fileNumber
		tTotalUserComboInfo.FileTotalSize = fileSize

		tx := provider.db.Table(table_name)
		if err := tx.Create(&tTotalUserComboInfo).Error; err != nil {
			LogError(LOG_EVENT_ID_MOD_TOTAL_USER_COMBO, utils.ERR_DB_INSERT_OPERATE_FAILED.Code,
				fmt.Sprintf("Add_Hour_UserCombo_Record %s %s '%s' %s-%s err:%v",
					object_type_name, userID, stat.StorageComboId,
					hourStart.Format("15:04"), hourEnd.Format("15:04"), err))
			continue
		}
		insertedCount++
	}

	LogInfo(LOG_EVENT_ID_MOD_TOTAL_USER_COMBO,
		fmt.Sprintf("Add_Hour_UserCombo_Record %s %s-%s: combos=%d inserted=%d skipped=%d empty=%d zeroStat=%d missingUserID=%d",
			object_type_name,
			hourStart.Format("15:04"), hourEnd.Format("15:04"),
			len(comboStats), insertedCount, skippedCount, emptyComboCount, zeroStatCount, missingUserIDCount))

	return nil
}

/*
 * @FuncName: 插入占位记录（用于避让机制）
 * @Version: v1.0.0
 * @Description: 当某对象类型在某小时完全没有任何数据时，插入一条所有数据=0的占位记录
 *               这样其他服务检查到该小时已有记录就会跳过，避免重复统计
 *
 * 向后兼容：
 *   - 即使统计数据为 0 也要保存到数据库
 *   - 用于多节点并发避让（防止重复统计）
 *   - 占位记录的 UserID 和 StorageComboId 都为空字符串
 *
 * @Param: object_type_name 对象类型名称
 * @Param: hourStart 小时开始时间（整点）
 * @Param: hourEnd 小时结束时间（整点）
 */
func (provider *MysqlProvider) insertPlaceholderRecord(object_type_name string, hourStart time.Time, hourEnd time.Time) error {

	// 表名称
	table_name := provider.getTableTypeName(&TTotalUserComboInfo{})

	// 先检查该对象类型在该小时是否已有任何记录
	existNum, err := provider.Query_ObjectType_Hour_Record_Number(object_type_name, hourStart, hourEnd)
	if err != nil {
		LogError(LOG_EVENT_ID_MOD_TOTAL_USER_COMBO, utils.ERR_DB_QUERY_OPERATE_FAILED.Code,
			fmt.Sprintf("insertPlaceholderRecord Query_ObjectType_Hour_Record_Number %s err = %v", object_type_name, err))
		return err
	}

	// 已有记录则跳过（避让）
	if existNum > 0 {
		LogInfo(LOG_EVENT_ID_MOD_TOTAL_USER_COMBO,
			fmt.Sprintf("insertPlaceholderRecord %s %s-%s already has %d records, skip",
				object_type_name, hourStart.Format("15:04"), hourEnd.Format("15:04"), existNum))
		return nil
	}

	// 组装占位记录（所有数据=0）
	var placeholder TTotalUserComboInfo
	placeholder.UserID = ""           // 占位记录 UserID 为空
	placeholder.StorageComboId = ""   // 占位记录 StorageComboId 为空
	placeholder.ObjectTypeName = object_type_name
	placeholder.StartTime = hourStart
	placeholder.EndTime = hourEnd
	placeholder.DeviceViidNumber = 0
	placeholder.ObjectNumber = 0
	placeholder.FileNumber = 0
	placeholder.FileTotalSize = 0

	// 插入占位记录
	if err := provider.db.Table(table_name).Create(&placeholder).Error; err != nil {
		LogError(LOG_EVENT_ID_MOD_TOTAL_USER_COMBO, utils.ERR_DB_INSERT_OPERATE_FAILED.Code,
			fmt.Sprintf("insertPlaceholderRecord %s %s-%s err: %v",
				object_type_name,
				hourStart.Format("15:04"), hourEnd.Format("15:04"), err))
		return err
	}

	LogInfo(LOG_EVENT_ID_MOD_TOTAL_USER_COMBO,
		fmt.Sprintf("insertPlaceholderRecord %s %s-%s inserted placeholder for avoidance",
			object_type_name,
			hourStart.Format("15:04"), hourEnd.Format("15:04")))

	return nil
}"}

